// Designed for 3D printing - sturdy construction for heavy towels

$fn = 64;

// Main parameters
wall_plate_width = 30;
wall_plate_height = 40;
wall_plate_thickness = 5;

// Hook parameters
hook_thickness = 8;          // Thick for strength
hook_width = 25;             // Wide hook for stability
hook_outer_radius = 20;      // Outer curve of hook
hook_inner_radius = 12;      // Inner curve (space for towel)
hook_extension = 35;         // How far hook extends from wall

// M3 flat head screw hole parameters
m3_shaft_diameter = 3.4;     // Slightly oversized for easy fit
m3_head_diameter = 6.5;      // M3 flat head is ~6mm
m3_head_depth = 2;           // Countersink depth

// Reinforcement/gusset parameters
gusset_height = 25;
gusset_depth = 20;

module wall_plate() {
    // Rounded rectangle plate that mounts to wall
    hull() {
        translate([wall_plate_width/2 - 5, 5, 0])
            cylinder(r=5, h=wall_plate_thickness);
        translate([-(wall_plate_width/2 - 5), 5, 0])
            cylinder(r=5, h=wall_plate_thickness);
        translate([wall_plate_width/2 - 5, wall_plate_height - 5, 0])
            cylinder(r=5, h=wall_plate_thickness);
        translate([-(wall_plate_width/2 - 5), wall_plate_height - 5, 0])
            cylinder(r=5, h=wall_plate_thickness);
    }
}

module screw_hole() {
    // M3 countersunk hole - positioned in upper portion of plate
    translate([0, wall_plate_height - 12, -1]) {
        // Shaft hole
        cylinder(d=m3_shaft_diameter, h=wall_plate_thickness + 2);
        // Countersink for flat head (from back side)
        translate([0, 0, wall_plate_thickness + 1 - m3_head_depth])
            cylinder(d1=m3_shaft_diameter, d2=m3_head_diameter, h=m3_head_depth + 0.1);
    }
}

module hook_arm() {
    // The extending arm portion
    translate([0, 0, wall_plate_thickness]) {
        // Main arm extending outward
        translate([-hook_width/2, -hook_extension + 5, 0])
            cube([hook_width, hook_extension, hook_thickness]);
    }
}

module hook_curve() {
    // The curved hook part at the end
    translate([0, -hook_extension + 5, wall_plate_thickness]) {
        difference() {
            // Outer curve
            rotate([0, 90, 0])
                translate([-hook_outer_radius, 0, -hook_width/2])
                    rotate_extrude(angle=180)
                        translate([hook_outer_radius - hook_thickness/2, 0, 0])
                            square([hook_thickness, hook_width]);

            // Cut off the back half that would go into wall
            translate([-hook_width/2 - 1, -hook_outer_radius - 1, -hook_outer_radius*2 - hook_thickness])
                cube([hook_width + 2, hook_outer_radius * 2 + 2, hook_outer_radius * 2]);
        }
    }
}

module hook_curved_end() {
    // J-shaped hook end
    translate([0, -hook_extension + 5, wall_plate_thickness + hook_thickness]) {
        rotate([90, 0, 90])
            translate([0, 0, -hook_width/2])
                linear_extrude(height=hook_width) {
                    // Create J-hook profile
                    difference() {
                        union() {
                            // Upward curve
                            translate([0, hook_outer_radius - hook_thickness])
                                difference() {
                                    circle(r=hook_outer_radius);
                                    circle(r=hook_inner_radius);
                                    // Keep only the front half (the J part)
                                    translate([-hook_outer_radius - 1, -hook_outer_radius*2 - 1])
                                        square([hook_outer_radius + 1, hook_outer_radius * 2 + 2]);
                                    // Cut top portion to make J shape
                                    translate([0, hook_outer_radius/2])
                                        square([hook_outer_radius + 1, hook_outer_radius]);
                                }
                        }
                    }
                }
    }
}

module gusset() {
    // Triangular reinforcement gusset for strength
    translate([0, 0, wall_plate_thickness]) {
        // Left gusset
        translate([-hook_width/2, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=3)
                    polygon([[0, 0], [-gusset_depth, 0], [0, gusset_height]]);

        // Right gusset
        translate([hook_width/2 - 3, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=3)
                    polygon([[0, 0], [-gusset_depth, 0], [0, gusset_height]]);

        // Center gusset for extra strength
        translate([-1.5, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=3)
                    polygon([[0, 0], [-gusset_depth, 0], [0, gusset_height]]);
    }
}

module towel_hook() {
    difference() {
        union() {
            // Wall mounting plate
            wall_plate();

            // Main hook arm
            hook_arm();

            // J-hook curved end
            hook_curved_end();

            // Reinforcement gussets
            gusset();

            // Fillet between plate and arm (rounded transition)
            translate([-hook_width/2, 0, wall_plate_thickness])
                cube([hook_width, 8, hook_thickness]);
        }

        // Subtract screw hole with countersink
        screw_hole();
    }
}

// Render the hook - oriented for 3D printing (plate flat on bed)
