            cylinder(d1=m3_shaft_diameter, d2=m3_head_diameter, h=m3_head_depth + 0.1);
    }
}

module hook_profile() {
    // 2D profile of the hook (side view)
    // Starting from wall plate, going down and curving into J

    arm_length = hook_extension - hook_curve_radius;

    union() {
        // Straight arm portion
        translate([0, -arm_length/2])
            square([hook_thickness, arm_length], center=true);

