m3_shaft_diameter = 3.4;     // Slightly oversized for easy fit
m3_head_diameter = 6.5;      // M3 flat head is ~6mm
m3_head_depth = 3;           // Countersink depth

// Reinforcement/gusset parameters
gusset_size = 25;
gusset_thickness = 5;

module wall_plate() {
    // Rounded rectangle plate that mounts to wall
    corner_r = 6;
    hull() {
        translate([wall_plate_width/2 - corner_r, corner_r, 0])
            cylinder(r=corner_r, h=wall_plate_thickness);
        translate([-(wall_plate_width/2 - corner_r), corner_r, 0])
            cylinder(r=corner_r, h=wall_plate_thickness);
        translate([wall_plate_width/2 - corner_r, wall_plate_height - corner_r, 0])
            cylinder(r=corner_r, h=wall_plate_thickness);
        translate([-(wall_plate_width/2 - corner_r), wall_plate_height - corner_r, 0])
            cylinder(r=corner_r, h=wall_plate_thickness);
    }
}

module screw_hole() {
    // M3 countersunk hole - positioned in upper portion of plate
    translate([0, wall_plate_height - 15, -0.1]) {
        // Shaft hole through entire plate
        cylinder(d=m3_shaft_diameter, h=wall_plate_thickness + 0.2);
        // Countersink for flat head (conical, from back/wall side)
        cylinder(d1=m3_head_diameter, d2=m3_shaft_diameter, h=m3_head_depth);
    }
}

module hook_2d_profile() {
    // 2D cross-section of the hook arm (for linear extrude)
    // Creates a rounded rectangle profile
    hull() {
        translate([hook_thickness/2 - 2, 2])
            circle(r=2);
        translate([-(hook_thickness/2 - 2), 2])
            circle(r=2);
        translate([hook_thickness/2 - 2, hook_thickness - 2])
            circle(r=2);
        translate([-(hook_thickness/2 - 2), hook_thickness - 2])
            circle(r=2);
    }
}

module hook_arm() {
    // Straight portion of hook extending from wall
    arm_length = hook_extension - hook_curve_radius;

    translate([0, 0, wall_plate_thickness])
        rotate([90, 0, 0])
            linear_extrude(height=arm_length)
                translate([-hook_width/2, 0])
                    square([hook_width, hook_thickness]);
}

module hook_j_curve() {
    // The J-shaped curved end
    inner_r = hook_curve_radius - hook_thickness/2;
    outer_r = hook_curve_radius + hook_thickness/2;

    translate([0, -(hook_extension - hook_curve_radius), wall_plate_thickness + hook_curve_radius]) {
        rotate([0, 90, 0])
            translate([0, 0, -hook_width/2])
                linear_extrude(height=hook_width)
                    // J curve - starts going down, curves around and up
                    intersection() {
                        difference() {
                            circle(r=outer_r);
                            circle(r=inner_r);
                        }
                        // Keep the portion from 0 to upturn_angle degrees
                        // 0 degrees = right (our "down" direction), rotating CCW
                        polygon([
                            [0, 0],
                            [outer_r + 5, 0],
                            [outer_r + 5, -(outer_r + 5)],
                            [(outer_r + 5) * cos(hook_upturn_angle), (outer_r + 5) * sin(hook_upturn_angle)],
                            for (a = [0 : 10 : hook_upturn_angle]) 
                                [(outer_r + 5) * cos(-a), (outer_r + 5) * sin(-a)]
                        ]);
                    }
    }
}

module gussets() {
    // Triangular reinforcement gussets for strength at the joint
    gusset_profile = [[0, 0], [0, gusset_size], [-gusset_size * 0.8, 0]];

    translate([0, 0, wall_plate_thickness]) {
        // Left gusset
        translate([-hook_width/2 + 0.1, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=gusset_thickness)
                    polygon(gusset_profile);

        // Right gusset  
        translate([hook_width/2 - gusset_thickness - 0.1, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=gusset_thickness)
                    polygon(gusset_profile);

        // Center gusset for extra strength
        translate([-gusset_thickness/2, 0, 0])
            rotate([90, 0, 90])
                linear_extrude(height=gusset_thickness)
                    polygon(gusset_profile);
    }
}

module connection_block() {
    // Solid block connecting plate to hook arm
    translate([-hook_width/2, -8, wall_plate_thickness])
        cube([hook_width, 16, hook_thickness]);
}

module towel_hook() {
    difference() {
        union() {
            // Wall mounting plate
            wall_plate();

            // Solid connection between plate and hook
            connection_block();

            // Main hook arm
            hook_arm();

            // J-curve at the end
            hook_j_curve();

            // Reinforcement gussets
            gussets();
        }

        // Subtract screw hole with countersink
        screw_hole();
    }
}

// Render the hook - oriented for 3D printing (plate flat on bed)
towel_hook();
